function sanitize(value, fallback) {
  const safe = (value ?? "")
    .replace(/[^A-Za-z0-9.&-]+/g, "-")
    .replace(/^[.-]+|[.-]+$/g, "")
    .slice(0, 60);
  return safe || fallback;
}

return $input.all().flatMap(({ json, binary }, item) => {
  const attachments = Object.values(binary ?? {});
  if (!attachments.length) return [];

  const uid = json.attributes?.uid;
  if (!Number.isSafeInteger(uid) || uid < 1) throw new Error("The email has no valid IMAP UID");

  const timestamp = new Date(json.date ?? NaN);
  const day = Number.isFinite(timestamp.getTime())
    ? timestamp.toISOString().slice(0, 10)
    : "undated";
  const sender = json.from?.value?.[0];
  const senderName = sanitize(sender?.name, "") || sanitize(sender?.address, "unknown-sender");

  return attachments.map((file, index) => {
    const originalName = file.fileName || "";
    const suffix = originalName.match(/\.[A-Za-z0-9]{1,15}$/);
    const extension = suffix?.index > 0 ? suffix[0] : "";
    const stem = sanitize(
      extension ? originalName.slice(0, -extension.length) : originalName,
      "attachment",
    );
    const fileName =
      day + "_" + senderName + "_" + stem + "_" + uid + "-" + (index + 1) + extension;
    return { json: { fileName }, binary: { file }, pairedItem: { item } };
  });
});
